INSERT INTO government_services (id, code, name, category, description, requirements, processing_info, icon, duration_minutes, requires_approval) VALUES
(1, 'NID', 'National Identification Services', 'Identity & Civil Registration', 'Apply for, renew or replace your national identity card, and update personal details on your record.', '["Completed application form","Original birth certificate","Parent or guardian ID (first-time applicants)","Two passport-size photographs"]', 'ID card ready in 7-10 working days', 'IdCard', 20, 0),
(2, 'PASS', 'Passport Applications', 'Travel & Transport', 'New passport applications, renewals and replacement of lost or damaged passports, including biometric capture.', '["National ID card","Completed passport application form","Proof of payment of the passport fee","Old passport (renewals)"]', 'Passport issued in 10-15 working days', 'Plane', 30, 0),
(3, 'BIRTH', 'Birth Certificate Registration', 'Identity & Civil Registration', 'Register a new birth or request a certified copy of an existing birth certificate.', '["Hospital birth notification","Parents'' national ID cards","Marriage certificate (if applicable)"]', 'Same-day issue for copies; new registrations in 5 working days', 'Baby', 20, 0),
(4, 'DL', 'Driving Licence Services', 'Travel & Transport', 'Apply for a new driving licence, renew an existing one or add a vehicle class.', '["National ID card","Valid medical certificate","Driving school certificate (new applicants)","Passport-size photograph"]', 'Licence issued in 5-7 working days', 'Car', 25, 0),
(5, 'BIZ', 'Business Registration', 'Business & Revenue', 'Register a sole proprietorship, partnership or company, and obtain your business certificate.', '["National ID of each owner","Proposed business name (3 options)","Business address details","Completed registration form"]', 'Certificate issued in 3-5 working days', 'Briefcase', 40, 0),
(6, 'TAX', 'Tax Services', 'Business & Revenue', 'Get a tax identification number, file returns with help from an officer, and resolve account queries.', '["National ID card","Previous tax returns (if any)","Income or business records"]', 'Tax number issued on the day', 'Receipt', 30, 0),
(7, 'LAND', 'Land Registration', 'Land & Property', 'Register a land transfer, lodge a title search or update ownership records. Bookings are confirmed by an officer.', '["Sale agreement or transfer deed","Original title deed","National ID cards of buyer and seller","Land rates clearance certificate"]', 'Processing takes 14-21 working days', 'Map', 45, 1),
(8, 'MARR', 'Marriage Certificate Services', 'Identity & Civil Registration', 'Register a civil marriage or request a certified copy of a marriage certificate.', '["National ID cards of both parties","Passport-size photographs of both parties","Two witnesses with ID cards"]', 'Certificate issued in 3 working days', 'Heart', 30, 0),
(9, 'CLR', 'Police Clearance Certificate', 'Justice & Security', 'Apply for a certificate of good conduct, with fingerprint capture at the office.', '["National ID card","Passport-size photograph","Proof of payment of the fee"]', 'Certificate issued in 5 working days', 'ShieldCheck', 25, 0),
(10, 'RES', 'Proof of Residence', 'Identity & Civil Registration', 'Obtain an official letter confirming your place of residence for banking, school or visa applications.', '["National ID card","Utility bill or tenancy agreement"]', 'Letter issued the same day', 'Home', 15, 0);
