-- Generated by server/scripts/generate-seed.js - sample data for testing.
-- Demo password for every account: Password@123
USE government_appointment_system;
SET @w = DATE_SUB(CURDATE(), INTERVAL WEEKDAY(CURDATE()) DAY);  -- Monday of the current week
SET FOREIGN_KEY_CHECKS = 0;
SET FOREIGN_KEY_CHECKS = 1;

-- Today's queue: for each office the earliest confirmed bookings of today are already served / being served.
CREATE TEMPORARY TABLE tmp_today AS
  SELECT id, ROW_NUMBER() OVER (PARTITION BY office_id ORDER BY appointment_time, id) AS rn
  FROM appointments WHERE appointment_date = CURDATE() AND status = 'Confirmed';
UPDATE appointments a JOIN tmp_today t ON t.id = a.id
  SET a.status = CASE WHEN t.rn <= 3 THEN 'Completed' WHEN t.rn = 4 THEN 'In Progress' WHEN t.rn <= 6 THEN 'Checked In' ELSE 'Confirmed' END;
DROP TEMPORARY TABLE tmp_today;

UPDATE appointments SET completed_at = TIMESTAMP(appointment_date, appointment_time) + INTERVAL 25 MINUTE WHERE status = 'Completed';

-- Slot usage always reflects the real (non-cancelled) bookings.
UPDATE time_slots s SET booked_count = (SELECT COUNT(*) FROM appointments a WHERE a.slot_id = s.id AND a.status <> 'Cancelled');

-- Queue records for everyone who was checked in.
SELECT a.id, a.office_id, a.appointment_date,
       ROW_NUMBER() OVER (PARTITION BY a.office_id, a.appointment_date ORDER BY a.appointment_time, a.id),
       CASE a.status WHEN 'Completed' THEN 'Completed' WHEN 'In Progress' THEN 'Serving' ELSE 'Waiting' END,
       CASE WHEN a.status IN ('Completed','In Progress') THEN CONCAT('Counter ', 1 + (a.id MOD 3)) ELSE NULL END,
       CASE WHEN a.status IN ('Completed','In Progress') THEN (SELECT u.id FROM users u WHERE u.office_id = a.office_id AND u.role_id = 2 LIMIT 1) ELSE NULL END,
       TIMESTAMP(a.appointment_date, a.appointment_time) - INTERVAL 8 MINUTE,
       CASE WHEN a.status IN ('Completed','In Progress') THEN TIMESTAMP(a.appointment_date, a.appointment_time) ELSE NULL END,
       CASE WHEN a.status = 'Completed' THEN TIMESTAMP(a.appointment_date, a.appointment_time) + INTERVAL 25 MINUTE ELSE NULL END
FROM appointments a WHERE a.status IN ('Completed','In Progress','Checked In');

-- Notifications (in-app) for every booking.
SELECT a.citizen_id, a.id,
       CASE WHEN a.status = 'Cancelled' THEN 'appointment_cancelled' WHEN a.status = 'Pending' THEN 'appointment_pending' ELSE 'appointment_confirmed' END,
       CASE WHEN a.status = 'Cancelled' THEN 'Appointment cancelled' WHEN a.status = 'Pending' THEN 'Appointment received' ELSE 'Appointment confirmed' END,
       CONCAT('Your appointment ', a.reference, ' for ', s.name, ' on ', DATE_FORMAT(a.appointment_date, '%a %d %b %Y'), ' at ', TIME_FORMAT(a.appointment_time, '%H:%i'),
              CASE WHEN a.status = 'Cancelled' THEN ' was cancelled.' WHEN a.status = 'Pending' THEN ' is awaiting confirmation by the office.' ELSE ' is confirmed.' END),
       CASE WHEN a.appointment_date < CURDATE() THEN 1 ELSE 0 END, a.booked_at
FROM appointments a JOIN government_services s ON s.id = a.service_id;

SELECT id, 'announcement', 'Welcome to GovBook', 'Book government appointments online, skip the queue and keep every confirmation in one place.', 0 FROM users WHERE role_id = 1;



